from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v22r2


class RndMode(v22r2.RndMode):
    def __init__(self, driver, download_checker):
        super(RndMode, self).__init__(driver, download_checker)
        self._fiveg_performance_test = NrPerformanceTestPage(driver)


class NrPerformanceTestPage(v22r2.rnd_mode.NrPerformanceTestPage):
    def __init__(self, driver):
        super(NrPerformanceTestPage, self).__init__(driver)
        self._view_panel = NrPerformanceTestPageViewPanel(driver)


class NrPerformanceTestPageViewPanel(v22r2.rnd_mode.NrPerformanceTestPageViewPanel):

    def __init__(self, driver):
        super(NrPerformanceTestPageViewPanel, self).__init__(driver)

    def _setup_common_params(self, *args, **kwargs):
        super(NrPerformanceTestPageViewPanel, self)._setup_common_params(*args, **kwargs)
        if kwargs['test_type'] == 'PUSCH':
            self._configure_mapping_type()

    def start_pusch_test(self, local_cell, frc_index, do_rate, do_type, rep_time_int, beam_id=None, ru_mode=None,
                         physical_cell_id=None, bb_selector=None, prb_offset=None, nrarfcn_downlink=None,
                         nrarfcn_uplink=None, nrarfcn=None, uci_bits_number=None, csi_bits_payload=None,
                         mapping_type='A', timeout=15):
        setattr(self, 'mapping_type', mapping_type)
        super(NrPerformanceTestPageViewPanel, self).start_pusch_test(local_cell=local_cell,
                                                                     frc_index=frc_index,
                                                                     do_rate=do_rate,
                                                                     do_type=do_type,
                                                                     rep_time_int=rep_time_int,
                                                                     beam_id=beam_id,
                                                                     ru_mode=ru_mode,
                                                                     physical_cell_id=physical_cell_id,
                                                                     bb_selector=bb_selector,
                                                                     prb_offset=prb_offset,
                                                                     nrarfcn_downlink=nrarfcn_downlink,
                                                                     nrarfcn_uplink=nrarfcn_uplink,
                                                                     nrarfcn=nrarfcn,
                                                                     uci_bits_number=uci_bits_number,
                                                                     csi_bits_payload=csi_bits_payload,
                                                                     timeout=int(timeout))

    def _configure_mapping_type(self):
        _MAPPING_TYPE_LIST_BUTTON_XPATH = '//div[contains(text(), "Mapping type")]/parent::*//button'
        _MAPPING_TYPE_LIST_OPTIONS_XPATH = '//div[contains(text(), "Mapping type")]/parent::*//ul//li'
        mapping_type = getattr(self, 'mapping_type', None)
        if mapping_type:
            self.select_element_from_dropdown_list_by_text_and_click(
                mapping_type,
                (By.XPATH, _MAPPING_TYPE_LIST_BUTTON_XPATH),
                (By.XPATH, _MAPPING_TYPE_LIST_OPTIONS_XPATH))

    def start_pucch_test(self, local_cell, rep_time_int=None, reception_slot=None, expectation_slot=None,
                         beam_id=None, ru_mode=None, physical_cell_id=None, pucch_format=None, prb_offset=None,
                         number_of_pucch_symbol=None, largest_prb_index=None, pucch_payload_content=None,
                         nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, f3_additional_dmrs=None, timeout=60):
        setattr(self, 'f3_additional_dmrs', f3_additional_dmrs)
        super(NrPerformanceTestPageViewPanel, self).start_pucch_test(local_cell=local_cell,
                                                                     rep_time_int=rep_time_int,
                                                                     reception_slot=reception_slot,
                                                                     expectation_slot=expectation_slot,
                                                                     beam_id=beam_id,
                                                                     ru_mode=ru_mode,
                                                                     physical_cell_id=physical_cell_id,
                                                                     pucch_format=pucch_format,
                                                                     prb_offset=prb_offset,
                                                                     number_of_pucch_symbol=number_of_pucch_symbol,
                                                                     largest_prb_index=largest_prb_index,
                                                                     pucch_payload_content=pucch_payload_content,
                                                                     nrarfcn_downlink=nrarfcn_downlink,
                                                                     nrarfcn_uplink=nrarfcn_uplink,
                                                                     nrarfcn=nrarfcn,
                                                                     timeout=int(timeout))

    def _basic_configure(self, params, timeout):
        super(NrPerformanceTestPageViewPanel, self)._basic_configure(params, timeout)
        self._configure_f3_additional_dmrs()

    def _configure_f3_additional_dmrs(self):
        _F3_ADDITINAL_DMRS_LIST_BUTTON_XPATH = '//div[contains(text(), "Format3 additional DMRS")]/parent::*//button'
        _F3_ADDITINAL_DMRS_LIST_OPTIONS_XPATH = '//div[contains(text(), "Format3 additional DMRS:")]/parent::*//ul//li'
        f3_additional_dmrs = getattr(self, 'f3_additional_dmrs', None)
        if f3_additional_dmrs:
            self.select_element_from_dropdown_list_by_text_and_click(
                f3_additional_dmrs,
                (By.XPATH, _F3_ADDITINAL_DMRS_LIST_BUTTON_XPATH),
                (By.XPATH, _F3_ADDITINAL_DMRS_LIST_OPTIONS_XPATH))
